from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/files/")
async def create_upload_file(token: str = Form(...), file: UploadFile = File(...)):
    return {"token": token, "filename": file.filename}

client = TestClient(app)

def test_form_then_file():
    # In this case, Form is declared BEFORE File
    response = client.post(
        "/files/", 
        data={"token": "foo"}, 
        files={"file": ("test.txt", b"content")}
    )
    assert response.status_code == 200, response.text
    assert response.json() == {"token": "foo", "filename": "test.txt"}

def test_file_then_form():
    # In this case, File is declared BEFORE Form (original working case)
    @app.post("/files_reversed/")
    async def create_upload_file_rev(file: UploadFile = File(...), token: str = Form(...)):
        return {"token": token, "filename": file.filename}

    response = client.post(
        "/files_reversed/", 
        data={"token": "foo"}, 
        files={"file": ("test.txt", b"content")}
    )
    assert response.status_code == 200, response.text
    assert response.json() == {"token": "foo", "filename": "test.txt"}
